function gridOver(canvas,cell,S){const c=canvas.getContext("2d");c.save();c.setTransform(S,0,0,S,0,0);c.beginPath();c.rect(MX,MY,MW,MH);c.clip();c.strokeStyle="rgba(20,16,10,.3)";c.lineWidth=1/S;c.beginPath();for(let x=MX;x<=MX+MW;x+=cell){c.moveTo(x,MY);c.lineTo(x,MY+MH)}for(let y=MY;y<=MY+MH;y+=cell*TILT){c.moveTo(MX,y);c.lineTo(MX+MW,y)}c.stroke();c.restore()}
// bairro sob um ponto do mundo
function patchAt(C,x,y){for(const p of C.patches){if(p.sea)continue;if(inPoly(p.poly,x,y))return p}return null}
// edicao de um objeto gerado (usada ao gerar e ao editar ao vivo)
const ARR=["B","SPB","props","trees","NAT","ships","boats","bunting","fields","squares","yards","STR","bridgesR"];
function applyOv(C,q,o){const isA=Array.isArray(q),own=ARR.find(n=>C[n]&&C[n].includes(q));if(!own)return;
  if(o.del){C[own].splice(C[own].indexOf(q),1);return}
  if(own==="squares"||own==="yards"){if(o.poly&&o.poly.length>=3)q.poly=o.poly.map(v=>[v[0],v[1]]);if(o.col)q.col=o.col;if(o.pave)q.pave=o.pave;return}
  if(own==="fields"){if(o.poly&&o.poly.length>=3){q.poly=o.poly.map(v=>[v[0],v[1]]);let sx=0,sy=0;for(const v of q.poly){sx+=v[0];sy+=v[1]}q.c=[sx/q.poly.length,sy/q.poly.length]}if(o.col)q.col=o.col;if(o.fence!=null)q.fence=o.fence;return}
  if(own==="bunting"){if(o.pa){q.a=[o.pa[0],o.pa[1]];q.b=[o.pb[0],o.pb[1]]}return}
  if(own==="bridgesR"){if(o.pa){q.a=[o.pa[0],o.pa[1]];q.b=[o.pb[0],o.pb[1]];q.m=[(q.a[0]+q.b[0])/2,(q.a[1]+q.b[1])/2]}if(o.stone!=null)q.stone=!!o.stone;if(o.wd)q.wd=o.wd;return}
  if(o.x!=null){if(isA){q[0]=o.x;q[1]=o.y}else{if(q.wing){q.wing.x+=o.x-q.x;q.wing.y+=o.y-q.y}q.x=o.x;q.y=o.y}}
  if(o.sc!=null&&!isA&&q.L){q.L0=q.L0||q.L;q.D0=q.D0||q.D;q.L=q.L0*o.sc;q.D=q.D0*o.sc;if(q.wing){q.wing.L0=q.wing.L0||q.wing.L;q.wing.D0=q.wing.D0||q.wing.D;q.wing.L=q.wing.L0*o.sc;q.wing.D=q.wing.D0*o.sc}}if(o.a!=null){q.ang=o.a;q.wing=null}if(o.fr!=null&&!isA){q.aov=Object.assign({},q.aov||{});if(o.fr)q.aov.fr=o.fr;else delete q.aov.fr}if(o.s!=null&&!isA&&q.id)q.s=o.s;if(o.v!=null)q.v=o.v;if(o.vs!=null)q.vs=o.vs;if(o.id)q.id=o.id;if(o.type)q.type=o.type;if(o.ms!=null)q.ms=o.ms;if(o.big!=null)q.big=o.big;if(o.ly!=null)q.ly=o.ly;
  if(isA){if(o.s!=null)q[2]=o.s;if(o.kind){const tree=o.kind==="tree"||o.kind==="wild",dst=tree?"trees":"NAT";q[3]=o.kind==="wild"?1:tree?0:o.kind;if(dst!==own){C[own].splice(C[own].indexOf(q),1);C[dst].push(q)}}}}
const DEFLY=[{id:"chao",name:"Chão"},{id:"base",name:"Principal"},{id:"frente",name:"Frente"}],FLATLY=new Set(["flowerbed","garden"]);
window.AtlasCity={GV,GVNOME,PRESETS,DEF_VOC,WMAT,WOPT,PALS,MARKS,IDOPT,Z,TILT,DEFLY,FLATLY,applyOv,renderTop,gridOver,generate,render,patchAt,DEF,PARAMS,SITES,WTYPES,CW,CH};
